"""Schema definition and migrations for both backends.

`SCHEMA_SQLITE` and `SCHEMA_POSTGRES` are kept deliberately close so the two
stay in step. Divergences are noted inline.

Portability rules used throughout:

* integer flags are ``SMALLINT`` on PostgreSQL, not ``BOOLEAN``, so the app's
  existing ``1 if x else 0`` writes and ``bool(row[...])`` reads both keep
  working unchanged.
* ``AUTOINCREMENT`` becomes ``GENERATED BY DEFAULT AS IDENTITY``; the id is
  still available as ``RETURNING id`` through the adapter.
* binary payloads are ``BYTEA``.
* full-text search is a generated ``tsvector`` column with a GIN index,
  instead of an FTS5 virtual table.
"""

from __future__ import annotations

import os
import re
from typing import Any

SEARCH_BODY_CHARS = int(os.getenv("FTS_BODY_CHARS", "4000"))

# ------------------------------------------------------------------ SQLite

SCHEMA_SQLITE = """
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    public_id TEXT NOT NULL UNIQUE,
    username TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('admin','user')),
    api_key_hash TEXT NOT NULL,
    api_key_prefix TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1,
    can_generate_codes INTEGER NOT NULL DEFAULT 0,
    referred_by INTEGER,
    created_via TEXT NOT NULL DEFAULT 'admin',
    created_ip TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY(referred_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_codes ON users(can_generate_codes);
CREATE INDEX IF NOT EXISTS idx_users_api_key_prefix ON users(api_key_prefix);

CREATE TABLE IF NOT EXISTS mailboxes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    address TEXT NOT NULL UNIQUE,
    owner_user_id INTEGER,
    exact_override INTEGER NOT NULL DEFAULT 0,
    override_reason TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_mailboxes_owner ON mailboxes(owner_user_id);

CREATE TABLE IF NOT EXISTS mailbox_access (
    mailbox_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    source TEXT NOT NULL DEFAULT 'manual',
    rule_id INTEGER,
    granted_by INTEGER,
    granted_at TEXT NOT NULL,
    PRIMARY KEY (mailbox_id, user_id),
    FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_access_user ON mailbox_access(user_id);

CREATE TABLE IF NOT EXISTS routing_rules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    rule_type TEXT NOT NULL CHECK(rule_type IN ('prefix','regex','domain','catch_all')),
    pattern TEXT NOT NULL,
    target_user_id INTEGER NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    is_active INTEGER NOT NULL DEFAULT 1,
    created_by INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_rules_target ON routing_rules(target_user_id);

CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mailbox_id INTEGER NOT NULL,
    envelope_from TEXT NOT NULL,
    envelope_to TEXT NOT NULL,
    subject TEXT NOT NULL DEFAULT '',
    message_id TEXT,
    received_at TEXT NOT NULL,
    otp TEXT,
    body_text TEXT,
    body_html TEXT,
    raw_mime BLOB,
    size_bytes INTEGER NOT NULL DEFAULT 0,
    raw_sha256 TEXT,
    has_attachments INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_messages_mailbox_received ON messages(mailbox_id, received_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_messages_received ON messages(received_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_messages_otp ON messages(mailbox_id, otp);
-- See ensure_messages_dedupe() in app.py — created after column migrations.

CREATE TABLE IF NOT EXISTS attachments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    message_id INTEGER NOT NULL,
    filename TEXT,
    content_type TEXT,
    disposition TEXT,
    content_id TEXT,
    content_location TEXT,
    size_bytes INTEGER NOT NULL DEFAULT 0,
    data BLOB,
    FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_attachments_message ON attachments(message_id);
CREATE INDEX IF NOT EXISTS idx_attachments_content_id ON attachments(message_id, content_id);

CREATE TABLE IF NOT EXISTS message_reads (
    message_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    read_at TEXT NOT NULL,
    PRIMARY KEY(message_id, user_id),
    FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    kind TEXT NOT NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL DEFAULT '',
    mailbox_id INTEGER,
    created_at TEXT NOT NULL,
    read_at TEXT,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    actor_user_id INTEGER,
    action TEXT NOT NULL,
    mailbox_id INTEGER,
    target_user_id INTEGER,
    details TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE SET NULL,
    FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);

CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token_hash TEXT NOT NULL UNIQUE,
    csrf_token TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);

CREATE TABLE IF NOT EXISTS app_settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS referral_codes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code_hash TEXT NOT NULL UNIQUE,
    code_fingerprint TEXT NOT NULL,
    owner_user_id INTEGER,
    created_by INTEGER,
    max_uses INTEGER NOT NULL DEFAULT 1,
    uses INTEGER NOT NULL DEFAULT 0,
    expires_at TEXT,
    is_active INTEGER NOT NULL DEFAULT 1,
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_referral_owner ON referral_codes(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_referral_created ON referral_codes(created_at DESC);

CREATE TABLE IF NOT EXISTS registrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    referral_code_id INTEGER,
    code_fingerprint TEXT,
    ip TEXT,
    user_agent TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY(referral_code_id) REFERENCES referral_codes(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_registrations_created ON registrations(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_registrations_user ON registrations(user_id);

CREATE TABLE IF NOT EXISTS domains (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    access_level TEXT NOT NULL DEFAULT 'public',
    description TEXT NOT NULL DEFAULT '',
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_domains_name ON domains(name);

CREATE TABLE IF NOT EXISTS mailbox_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    desired_address TEXT NOT NULL,
    reason TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'pending',
    admin_note TEXT NOT NULL DEFAULT '',
    reviewed_by INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_mb_requests_user ON mailbox_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_mb_requests_status ON mailbox_requests(status);

CREATE TABLE IF NOT EXISTS outbound_messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mailbox_id INTEGER NOT NULL,
    sent_by_user_id INTEGER,
    to_addrs TEXT NOT NULL DEFAULT '[]',
    cc_addrs TEXT NOT NULL DEFAULT '[]',
    bcc_addrs TEXT NOT NULL DEFAULT '[]',
    subject TEXT NOT NULL DEFAULT '',
    body_text TEXT,
    body_html TEXT,
    cf_message_id TEXT,
    status TEXT NOT NULL DEFAULT 'sent',
    error TEXT NOT NULL DEFAULT '',
    size_bytes INTEGER NOT NULL DEFAULT 0,
    has_attachments INTEGER NOT NULL DEFAULT 0,
    sent_at TEXT NOT NULL,
    FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE,
    FOREIGN KEY(sent_by_user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_outbound_mailbox_sent ON outbound_messages(mailbox_id, sent_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_outbound_sent ON outbound_messages(sent_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_outbound_user ON outbound_messages(sent_by_user_id, sent_at DESC);
"""

# -------------------------------------------------------------- PostgreSQL

# `search_vector` is a stored generated column so it can never drift from the
# text it indexes. `simple` is used on purpose: no stemming and no dictionary,
# which keeps OTP-style short tokens and non-English text indexable.
_SEARCH_VECTOR = f"""search_vector tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('simple', coalesce(subject, '')), 'A') ||
        setweight(to_tsvector('simple', coalesce(envelope_from, '')), 'A') ||
        setweight(to_tsvector('simple', coalesce(envelope_to, '')), 'B') ||
        setweight(to_tsvector('simple', coalesce(otp, '')), 'A') ||
        setweight(to_tsvector('simple', left(coalesce(body_text, ''), {SEARCH_BODY_CHARS})), 'D')
    ) STORED"""

SCHEMA_POSTGRES = """
CREATE TABLE IF NOT EXISTS users (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id text NOT NULL UNIQUE,
    username text NOT NULL UNIQUE,
    password_hash text NOT NULL,
    role text NOT NULL CHECK(role IN ('admin','user')),
    api_key_hash text NOT NULL,
    api_key_prefix text NOT NULL,
    is_active smallint NOT NULL DEFAULT 1,
    can_generate_codes smallint NOT NULL DEFAULT 0,
    referred_by integer REFERENCES users(id) ON DELETE SET NULL,
    created_via text NOT NULL DEFAULT 'admin',
    created_ip text,
    created_at text NOT NULL,
    updated_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_codes ON users(can_generate_codes);
CREATE INDEX IF NOT EXISTS idx_users_api_key_prefix ON users(api_key_prefix);

-- Declared before mailbox_access, because that table's rule_id references it
-- and PostgreSQL requires the referenced table to already exist.
CREATE TABLE IF NOT EXISTS routing_rules (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rule_type text NOT NULL CHECK(rule_type IN ('prefix','regex','domain','catch_all')),
    pattern text NOT NULL,
    target_user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    description text NOT NULL DEFAULT '',
    is_active smallint NOT NULL DEFAULT 1,
    created_by integer REFERENCES users(id) ON DELETE SET NULL,
    created_at text NOT NULL,
    updated_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_rules_target ON routing_rules(target_user_id);

CREATE TABLE IF NOT EXISTS mailboxes (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    address text NOT NULL UNIQUE,
    owner_user_id integer REFERENCES users(id) ON DELETE SET NULL,
    exact_override smallint NOT NULL DEFAULT 0,
    override_reason text,
    created_at text NOT NULL,
    updated_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_mailboxes_owner ON mailboxes(owner_user_id);

CREATE TABLE IF NOT EXISTS mailbox_access (
    mailbox_id integer NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    source text NOT NULL DEFAULT 'manual',
    rule_id integer REFERENCES routing_rules(id) ON DELETE SET NULL,
    granted_by integer REFERENCES users(id) ON DELETE SET NULL,
    granted_at text NOT NULL,
    PRIMARY KEY (mailbox_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_access_user ON mailbox_access(user_id);

CREATE TABLE IF NOT EXISTS messages (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mailbox_id integer NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
    envelope_from text NOT NULL,
    envelope_to text NOT NULL,
    subject text NOT NULL DEFAULT '',
    message_id text,
    received_at text NOT NULL,
    otp text,
    body_text text,
    body_html text,
    raw_mime bytea,
    size_bytes integer NOT NULL DEFAULT 0,
    raw_sha256 text,
    has_attachments smallint NOT NULL DEFAULT 0,
    """ + _SEARCH_VECTOR + """
);
CREATE INDEX IF NOT EXISTS idx_messages_mailbox_received ON messages(mailbox_id, received_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_messages_received ON messages(received_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_messages_otp ON messages(mailbox_id, otp);
-- Dedupe unique index is created in ensure_messages_dedupe() after migrations,
-- so existing DBs with duplicate (mailbox_id, raw_sha256) rows can be cleaned first.
CREATE INDEX IF NOT EXISTS idx_messages_search ON messages USING GIN (search_vector);

CREATE TABLE IF NOT EXISTS attachments (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    message_id integer NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    filename text,
    content_type text,
    disposition text,
    content_id text,
    content_location text,
    size_bytes integer NOT NULL DEFAULT 0,
    data bytea
);
CREATE INDEX IF NOT EXISTS idx_attachments_message ON attachments(message_id);
CREATE INDEX IF NOT EXISTS idx_attachments_content_id ON attachments(message_id, content_id);

CREATE TABLE IF NOT EXISTS message_reads (
    message_id integer NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    read_at text NOT NULL,
    PRIMARY KEY(message_id, user_id)
);

CREATE TABLE IF NOT EXISTS notifications (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind text NOT NULL,
    title text NOT NULL,
    body text NOT NULL DEFAULT '',
    mailbox_id integer REFERENCES mailboxes(id) ON DELETE SET NULL,
    created_at text NOT NULL,
    read_at text
);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS audit_logs (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_user_id integer REFERENCES users(id) ON DELETE SET NULL,
    action text NOT NULL,
    mailbox_id integer REFERENCES mailboxes(id) ON DELETE SET NULL,
    target_user_id integer REFERENCES users(id) ON DELETE SET NULL,
    details text NOT NULL DEFAULT '',
    created_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);

CREATE TABLE IF NOT EXISTS sessions (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash text NOT NULL UNIQUE,
    csrf_token text NOT NULL,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at text NOT NULL,
    created_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);

CREATE TABLE IF NOT EXISTS app_settings (
    key text PRIMARY KEY,
    value text NOT NULL,
    updated_at text NOT NULL
);

CREATE TABLE IF NOT EXISTS referral_codes (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code_hash text NOT NULL UNIQUE,
    code_fingerprint text NOT NULL,
    owner_user_id integer REFERENCES users(id) ON DELETE CASCADE,
    created_by integer REFERENCES users(id) ON DELETE SET NULL,
    max_uses integer NOT NULL DEFAULT 1,
    uses integer NOT NULL DEFAULT 0,
    expires_at text,
    is_active smallint NOT NULL DEFAULT 1,
    note text NOT NULL DEFAULT '',
    created_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_referral_owner ON referral_codes(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_referral_created ON referral_codes(created_at DESC);

CREATE TABLE IF NOT EXISTS registrations (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    referral_code_id integer REFERENCES referral_codes(id) ON DELETE SET NULL,
    code_fingerprint text,
    ip text,
    user_agent text,
    created_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_registrations_created ON registrations(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_registrations_user ON registrations(user_id);

CREATE TABLE IF NOT EXISTS domains (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name text NOT NULL UNIQUE,
    access_level text NOT NULL DEFAULT 'public',
    description text NOT NULL DEFAULT '',
    is_active smallint NOT NULL DEFAULT 1,
    created_at text NOT NULL,
    updated_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_domains_name ON domains(name);

CREATE TABLE IF NOT EXISTS mailbox_requests (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    desired_address text NOT NULL,
    reason text NOT NULL DEFAULT '',
    status text NOT NULL DEFAULT 'pending',
    admin_note text NOT NULL DEFAULT '',
    reviewed_by integer REFERENCES users(id) ON DELETE SET NULL,
    created_at text NOT NULL,
    updated_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_mb_requests_user ON mailbox_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_mb_requests_status ON mailbox_requests(status);

CREATE TABLE IF NOT EXISTS outbound_messages (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mailbox_id integer NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
    sent_by_user_id integer REFERENCES users(id) ON DELETE SET NULL,
    to_addrs text NOT NULL DEFAULT '[]',
    cc_addrs text NOT NULL DEFAULT '[]',
    bcc_addrs text NOT NULL DEFAULT '[]',
    subject text NOT NULL DEFAULT '',
    body_text text,
    body_html text,
    cf_message_id text,
    status text NOT NULL DEFAULT 'sent',
    error text NOT NULL DEFAULT '',
    size_bytes integer NOT NULL DEFAULT 0,
    has_attachments smallint NOT NULL DEFAULT 0,
    sent_at text NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_outbound_mailbox_sent ON outbound_messages(mailbox_id, sent_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_outbound_sent ON outbound_messages(sent_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_outbound_user ON outbound_messages(sent_by_user_id, sent_at DESC);
"""

# Column additions for databases created before a feature existed. Each entry
# is (table, column, sqlite_ddl, postgres_ddl).
MIGRATIONS = [
    ("users", "is_active", "is_active INTEGER NOT NULL DEFAULT 1", "is_active smallint NOT NULL DEFAULT 1"),
    ("users", "updated_at", "updated_at TEXT", "updated_at text"),
    ("users", "can_generate_codes", "can_generate_codes INTEGER NOT NULL DEFAULT 0", "can_generate_codes smallint NOT NULL DEFAULT 0"),
    ("users", "referred_by", "referred_by INTEGER", "referred_by integer"),
    ("users", "created_via", "created_via TEXT NOT NULL DEFAULT 'admin'", "created_via text NOT NULL DEFAULT 'admin'"),
    ("users", "created_ip", "created_ip TEXT", "created_ip text"),
    ("mailboxes", "exact_override", "exact_override INTEGER NOT NULL DEFAULT 0", "exact_override smallint NOT NULL DEFAULT 0"),
    ("mailboxes", "override_reason", "override_reason TEXT", "override_reason text"),
    ("mailboxes", "updated_at", "updated_at TEXT", "updated_at text"),
    ("messages", "raw_sha256", "raw_sha256 TEXT", "raw_sha256 text"),
    ("messages", "has_attachments", "has_attachments INTEGER NOT NULL DEFAULT 0", "has_attachments smallint NOT NULL DEFAULT 0"),
    ("mailbox_access", "source", "source TEXT NOT NULL DEFAULT 'manual'", "source text NOT NULL DEFAULT 'manual'"),
    ("mailbox_access", "rule_id", "rule_id INTEGER", "rule_id integer"),
]


def schema_for(postgres: bool) -> str:
    return SCHEMA_POSTGRES if postgres else SCHEMA_SQLITE


def ddl_for(index: int, postgres: bool) -> str:
    return MIGRATIONS[index][3] if postgres else MIGRATIONS[index][2]
